function maximumSubarraySum(nums, k) {
  let best = 0;
  for (let start = 0; start + k <= nums.length; start++) {
    const block = nums.slice(start, start + k);
    if (new Set(block).size !== k) continue;
    best = Math.max(best, block.reduce((acc, v) => acc + v, 0));
  }
  return best;
}

