    const n = 2000;
    const k = rand() < 0.5 ? 1 + Math.floor(rand() * 40) : 1 + Math.floor(rand() * 600);
    // A narrow value range makes repeats common; a wide one leaves most windows distinct.
    const high = rand() < 0.5 ? 100000 : Math.min(100000, k + Math.floor(rand() * 2 * k) + 1);
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * high)), k];
  }
  const n = 1 + Math.floor(rand() * 9);
  const k = 1 + Math.floor(rand() * n);
  const high = 1 + Math.floor(rand() * 8);
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * high)), k];
}
